/** @module Interface wonderful:date/functions **/
/**
 * Create a duration object from individual time components
 * 
 * ### Arguments
 * * `years` - Number of years
 * * `months` - Number of months
 * * `days` - Number of days
 * * `hours` - Number of hours
 * * `minutes` - Number of minutes
 * * `seconds` - Number of seconds
 * * `milliseconds` - Number of milliseconds
 * 
 * ### Returns
 * A duration object containing all the specified time components
 */
export function createDuration(years: number, months: number, days: number, hours: number, minutes: number, seconds: number, milliseconds: number): Duration;
/**
 * Calculate the duration between two moments
 * 
 * ### Arguments
 * * `start` - The starting moment
 * * `end` - The ending moment
 * 
 * ### Returns
 * A duration representing the time difference between start and end moments
 */
export function durationBetween(start: Moment, end: Moment): Duration;
export type Error = ErrorInvalidTimezone | ErrorInvalidIsoString | ErrorInvalidFormat | ErrorParseError | ErrorInvalidDateComponents | ErrorInvalidTimeComponents | ErrorAmbiguousLocalTime | ErrorOutOfRangeMonth | ErrorOutOfRangeDay | ErrorOutOfRangeHour | ErrorOutOfRangeMinute | ErrorOutOfRangeSecond | ErrorOutOfRangeMillisecond | ErrorInvalidDate | ErrorInvalidTime | ErrorOther;
export interface ErrorInvalidTimezone {
  tag: 'invalid-timezone',
  val: string,
}
export interface ErrorInvalidIsoString {
  tag: 'invalid-iso-string',
  val: string,
}
export interface ErrorInvalidFormat {
  tag: 'invalid-format',
  val: string,
}
export interface ErrorParseError {
  tag: 'parse-error',
  val: string,
}
export interface ErrorInvalidDateComponents {
  tag: 'invalid-date-components',
  val: string,
}
export interface ErrorInvalidTimeComponents {
  tag: 'invalid-time-components',
  val: string,
}
export interface ErrorAmbiguousLocalTime {
  tag: 'ambiguous-local-time',
  val: string,
}
export interface ErrorOutOfRangeMonth {
  tag: 'out-of-range-month',
  val: string,
}
export interface ErrorOutOfRangeDay {
  tag: 'out-of-range-day',
  val: string,
}
export interface ErrorOutOfRangeHour {
  tag: 'out-of-range-hour',
  val: string,
}
export interface ErrorOutOfRangeMinute {
  tag: 'out-of-range-minute',
  val: string,
}
export interface ErrorOutOfRangeSecond {
  tag: 'out-of-range-second',
  val: string,
}
export interface ErrorOutOfRangeMillisecond {
  tag: 'out-of-range-millisecond',
  val: string,
}
export interface ErrorInvalidDate {
  tag: 'invalid-date',
  val: string,
}
export interface ErrorInvalidTime {
  tag: 'invalid-time',
  val: string,
}
export interface ErrorOther {
  tag: 'other',
  val: string,
}
export interface DateComponents {
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  millisecond: number,
}
export interface TimezoneInfo {
  /**
   * IANA timezone name (e.g., "America/New_York")
   */
  name: string,
  /**
   * timezone abbreviation (e.g., "EST", "EDT")
   */
  abbreviation: string,
  /**
   * offset from UTC in minutes
   */
  offsetMinutes: number,
  /**
   * whether daylight saving time is active
   */
  isDst: boolean,
}
export interface Duration {
  years: number,
  months: number,
  days: number,
  hours: number,
  minutes: number,
  seconds: number,
  milliseconds: number,
}

export class Moment {
  /**
  * Create a new `Moment` object from an ISO date string
  * 
  * ### Arguments
  * * `date` - ISO 8601 date string (e.g., "2025-10-01T12:18:12.884+03:00")
  */
  constructor(date: string)
  /**
  * Parse an ISO date string into a `Moment`
  * 
  * ### Arguments
  * * `date` - ISO 8601 date string (must include timezone/offset)
  * 
  * ### Returns
  * A new `Moment` instance, or an error if parsing fails
  */
  static parse(date: string): Moment;
  /**
  * Create a `Moment` representing the current date and time in UTC+00
  * 
  * ### Returns
  * A new `Moment` instance set to the current time
  */
  static now(): Moment;
  /**
  * Create a UTC `Moment` from an ISO date string
  * 
  * ### Arguments
  * * `date` - ISO 8601 date string to parse in UTC
  * 
  * ### Returns
  * A new `Moment` instance in UTC timezone, or an error if parsing fails
  */
  static utc(date: string): Moment;
  /**
  * Create a `Moment` from a Unix timestamp in milliseconds
  * 
  * ### Arguments
  * * `timestamp-millis` - Unix timestamp in milliseconds since epoch
  * 
  * ### Returns
  * A new `Moment` instance representing the given timestamp
  */
  static fromTimestamp(timestampMillis: bigint): Moment;
  /**
  * Create a `Moment` from individual date components
  * 
  * ### Arguments
  * * `components` - Date components (year, month, day, hour, minute, second, millisecond)
  * * `timezone` - Optional IANA timezone name (e.g., "America/New_York")
  * 
  * ### Returns
  * A new `Moment` instance, or an error if components are invalid
  */
  static fromComponents(components: DateComponents, timezone: string | undefined): Moment;
  /**
  * Format `Moment` using a custom format string
  * 
  * ### Arguments
  * * `format-string` - Format string (e.g., "YYYY-MM-DD HH:mm:ss")
  * 
  * ### Returns
  * Formatted date string according to the format specification
  */
  format(formatString: string): string;
  /**
  * Convert `Moment` to an ISO 8601 string
  * 
  * ### Returns
  * ISO 8601 formatted string (e.g., "2025-10-01T12:18:12.884Z")
  */
  toIsoString(): string;
  /**
  * Convert `Moment` to a date string
  * 
  * ### Returns
  * Human-readable date string (e.g., "Mon Oct 01 2025")
  */
  toDateString(): string;
  /**
  * Convert `Moment` to a time string
  * 
  * ### Returns
  * Human-readable time string (e.g., "12:18:12 GMT+0300")
  */
  toTimeString(): string;
  /**
  * Convert `Moment` to a JSON-compatible string
  * 
  * ### Returns
  * JSON-serializable ISO string representation
  */
  toJson(): string;
  /**
  * Convert `Moment` to a different timezone
  * 
  * ### Arguments
  * * `timezone` - IANA timezone name (e.g., "Asia/Jerusalem", "Europe/London")
  * 
  * ### Returns
  * A new `Moment` instance in the specified timezone, or an error if timezone is invalid
  */
  tz(timezone: string): Moment;
  /**
  * Get the UTC offset in minutes for the current timezone
  * 
  * ### Returns
  * UTC offset in minutes (positive for east of UTC, negative for west)
  */
  utcOffset(): number;
  /**
  * Get detailed timezone information
  * 
  * ### Returns
  * Timezone information including name, abbreviation, offset, and DST status
  */
  timezoneInfo(): TimezoneInfo;
  /**
  * Check if the moment is currently in daylight saving time
  * 
  * ### Returns
  * True if DST is active, false otherwise
  */
  isDst(): boolean;
  /**
  * Get the year component
  * 
  * ### Returns
  * The year (e.g., 2025)
  */
  year(): number;
  /**
  * Get the month component
  * 
  * ### Returns
  * The month (1-12, where 1 = January)
  */
  month(): number;
  /**
  * Get the day of month component
  * 
  * ### Returns
  * The day of the month (1-31)
  */
  day(): number;
  /**
  * Get the hour component
  * 
  * ### Returns
  * The hour in 24-hour format (0-23)
  */
  hour(): number;
  /**
  * Get the minute component
  * 
  * ### Returns
  * The minute (0-59)
  */
  minute(): number;
  /**
  * Get the second component
  * 
  * ### Returns
  * The second (0-59)
  */
  second(): number;
  /**
  * Get the millisecond component
  * 
  * ### Returns
  * The millisecond (0-999)
  */
  millisecond(): number;
  /**
  * Get the day of the week
  * 
  * ### Returns
  * Day of week (0 = Sunday, 1 = Monday, ..., 6 = Saturday)
  */
  dayOfWeek(): number;
  /**
  * Get the day of the year
  * 
  * ### Returns
  * Day of year (1-366, accounting for leap years)
  */
  dayOfYear(): number;
  /**
  * Get the week of the year
  * 
  * ### Returns
  * Week of year (1-53, ISO week numbering)
  */
  weekOfYear(): number;
  /**
  * Get the Unix timestamp in milliseconds
  * 
  * ### Returns
  * Unix timestamp in milliseconds since epoch (January 1, 1970 UTC)
  */
  timestamp(): bigint;
  /**
  * Get the Unix timestamp in seconds
  * 
  * ### Returns
  * Unix timestamp in seconds since epoch (January 1, 1970 UTC)
  */
  timestampSeconds(): bigint;
  /**
  * Set the year component (returns new instance)
  * 
  * ### Arguments
  * * `year` - The year to set (e.g., 2025)
  * 
  * ### Returns
  * A new `Moment` instance with the specified year
  */
  setYear(year: number): Moment;
  /**
  * Set the month component (returns new instance)
  * 
  * ### Arguments
  * * `month` - The month to set (1-12, where 1 = January)
  * 
  * ### Returns
  * A new `Moment` instance with the specified month, or an error if invalid
  */
  setMonth(month: number): Moment;
  /**
  * Set the day component (returns new instance)
  * 
  * ### Arguments
  * * `day` - The day of month to set (1-31)
  * 
  * ### Returns
  * A new `Moment` instance with the specified day, or an error if invalid
  */
  setDay(day: number): Moment;
  /**
  * Set the hour component (returns new instance)
  * 
  * ### Arguments
  * * `hour` - The hour to set (0-23)
  * 
  * ### Returns
  * A new `Moment` instance with the specified hour, or an error if invalid
  */
  setHour(hour: number): Moment;
  /**
  * Set the minute component (returns new instance)
  * 
  * ### Arguments
  * * `minute` - The minute to set (0-59)
  * 
  * ### Returns
  * A new `Moment` instance with the specified minute, or an error if invalid
  */
  setMinute(minute: number): Moment;
  /**
  * Set the second component (returns new instance)
  * 
  * ### Arguments
  * * `second` - The second to set (0-59)
  * 
  * ### Returns
  * A new `Moment` instance with the specified second, or an error if invalid
  */
  setSecond(second: number): Moment;
  /**
  * Set the millisecond component (returns new instance)
  * 
  * ### Arguments
  * * `millisecond` - The millisecond to set (0-999)
  * 
  * ### Returns
  * A new `Moment` instance with the specified millisecond, or an error if invalid
  */
  setMillisecond(millisecond: number): Moment;
  /**
  * Add years to the moment (returns new instance)
  * 
  * ### Arguments
  * * `years` - Number of years to add (can be negative to subtract)
  * 
  * ### Returns
  * A new `Moment` instance with years added
  */
  addYears(years: number): Moment;
  /**
  * Add months to the moment (returns new instance)
  * 
  * ### Arguments
  * * `months` - Number of months to add (can be negative to subtract)
  * 
  * ### Returns
  * A new `Moment` instance with months added
  */
  addMonths(months: number): Moment;
  /**
  * Add days to the moment (returns new instance)
  * 
  * ### Arguments
  * * `days` - Number of days to add (can be negative to subtract)
  * 
  * ### Returns
  * A new `Moment` instance with days added
  */
  addDays(days: number): Moment;
  /**
  * Add hours to the moment (returns new instance)
  * 
  * ### Arguments
  * * `hours` - Number of hours to add (can be negative to subtract)
  * 
  * ### Returns
  * A new `Moment` instance with hours added
  */
  addHours(hours: number): Moment;
  /**
  * Add minutes to the moment (returns new instance)
  * 
  * ### Arguments
  * * `minutes` - Number of minutes to add (can be negative to subtract)
  * 
  * ### Returns
  * A new `Moment` instance with minutes added
  */
  addMinutes(minutes: number): Moment;
  /**
  * Add seconds to the moment (returns new instance)
  * 
  * ### Arguments
  * * `seconds` - Number of seconds to add (can be negative to subtract)
  * 
  * ### Returns
  * A new `Moment` instance with seconds added
  */
  addSeconds(seconds: number): Moment;
  /**
  * Add milliseconds to the moment (returns new instance)
  * 
  * ### Arguments
  * * `milliseconds` - Number of milliseconds to add (can be negative to subtract)
  * 
  * ### Returns
  * A new `Moment` instance with milliseconds added
  */
  addMilliseconds(milliseconds: number): Moment;
  /**
  * Add a duration to the moment (returns new instance)
  * 
  * ### Arguments
  * * `duration` - Duration object containing years, months, days, hours, minutes, seconds, milliseconds
  * 
  * ### Returns
  * A new `Moment` instance with the duration added
  */
  addDuration(duration: Duration): Moment;
  /**
  * Subtract years from the moment (returns new instance)
  * 
  * ### Arguments
  * * `years` - Number of years to subtract
  * 
  * ### Returns
  * A new `Moment` instance with years subtracted
  */
  subtractYears(years: number): Moment;
  /**
  * Subtract months from the moment (returns new instance)
  * 
  * ### Arguments
  * * `months` - Number of months to subtract
  * 
  * ### Returns
  * A new `Moment` instance with months subtracted
  */
  subtractMonths(months: number): Moment;
  /**
  * Subtract days from the moment (returns new instance)
  * 
  * ### Arguments
  * * `days` - Number of days to subtract
  * 
  * ### Returns
  * A new `Moment` instance with days subtracted
  */
  subtractDays(days: number): Moment;
  /**
  * Subtract hours from the moment (returns new instance)
  * 
  * ### Arguments
  * * `hours` - Number of hours to subtract
  * 
  * ### Returns
  * A new `Moment` instance with hours subtracted
  */
  subtractHours(hours: number): Moment;
  /**
  * Subtract minutes from the moment (returns new instance)
  * 
  * ### Arguments
  * * `minutes` - Number of minutes to subtract
  * 
  * ### Returns
  * A new `Moment` instance with minutes subtracted
  */
  subtractMinutes(minutes: number): Moment;
  /**
  * Subtract seconds from the moment (returns new instance)
  * 
  * ### Arguments
  * * `seconds` - Number of seconds to subtract
  * 
  * ### Returns
  * A new `Moment` instance with seconds subtracted
  */
  subtractSeconds(seconds: number): Moment;
  /**
  * Subtract milliseconds from the moment (returns new instance)
  * 
  * ### Arguments
  * * `milliseconds` - Number of milliseconds to subtract
  * 
  * ### Returns
  * A new `Moment` instance with milliseconds subtracted
  */
  subtractMilliseconds(milliseconds: number): Moment;
  /**
  * Subtract a duration from the moment (returns new instance)
  * 
  * ### Arguments
  * * `duration` - Duration object to subtract
  * 
  * ### Returns
  * A new `Moment` instance with the duration subtracted
  */
  subtractDuration(duration: Duration): Moment;
  /**
  * Get the start of the year (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to January 1st, 00:00:00.000 of the same year
  */
  startOfYear(): Moment;
  /**
  * Get the start of the month (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to the 1st day, 00:00:00.000 of the same month
  */
  startOfMonth(): Moment;
  /**
  * Get the start of the day (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to 00:00:00.000 of the same day
  */
  startOfDay(): Moment;
  /**
  * Get the start of the hour (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to XX:00:00.000 of the same hour
  */
  startOfHour(): Moment;
  /**
  * Get the start of the minute (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to XX:XX:00.000 of the same minute
  */
  startOfMinute(): Moment;
  /**
  * Get the start of the second (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to XX:XX:XX.000 of the same second
  */
  startOfSecond(): Moment;
  /**
  * Get the end of the year (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to December 31st, 23:59:59.999 of the same year
  */
  endOfYear(): Moment;
  /**
  * Get the end of the month (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to the last day, 23:59:59.999 of the same month
  */
  endOfMonth(): Moment;
  /**
  * Get the end of the day (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to 23:59:59.999 of the same day
  */
  endOfDay(): Moment;
  /**
  * Get the end of the hour (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to XX:59:59.999 of the same hour
  */
  endOfHour(): Moment;
  /**
  * Get the end of the minute (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to XX:XX:59.999 of the same minute
  */
  endOfMinute(): Moment;
  /**
  * Get the end of the second (returns new instance)
  * 
  * ### Returns
  * A new `Moment` instance set to XX:XX:XX.999 of the same second
  */
  endOfSecond(): Moment;
  /**
  * Check if this moment is before another moment
  * 
  * ### Arguments
  * * `other` - The moment to compare against
  * 
  * ### Returns
  * True if this moment is before the other moment
  */
  isBefore(other: Moment): boolean;
  /**
  * Check if this moment is after another moment
  * 
  * ### Arguments
  * * `other` - The moment to compare against
  * 
  * ### Returns
  * True if this moment is after the other moment
  */
  isAfter(other: Moment): boolean;
  /**
  * Check if this moment is the same as another moment
  * 
  * ### Arguments
  * * `other` - The moment to compare against
  * 
  * ### Returns
  * True if both moments represent the exact same time
  */
  isSame(other: Moment): boolean;
  /**
  * Check if this moment is the same or before another moment
  * 
  * ### Arguments
  * * `other` - The moment to compare against
  * 
  * ### Returns
  * True if this moment is the same or before the other moment
  */
  isSameOrBefore(other: Moment): boolean;
  /**
  * Check if this moment is the same or after another moment
  * 
  * ### Arguments
  * * `other` - The moment to compare against
  * 
  * ### Returns
  * True if this moment is the same or after the other moment
  */
  isSameOrAfter(other: Moment): boolean;
  /**
  * Calculate the difference in milliseconds between this and another moment
  * 
  * ### Arguments
  * * `other` - The moment to calculate difference from
  * 
  * ### Returns
  * Difference in milliseconds (positive if this moment is after the other)
  */
  diffMilliseconds(other: Moment): bigint;
  /**
  * Calculate the difference in seconds between this and another moment
  * 
  * ### Arguments
  * * `other` - The moment to calculate difference from
  * 
  * ### Returns
  * Difference in seconds (positive if this moment is after the other)
  */
  diffSeconds(other: Moment): bigint;
  /**
  * Calculate the difference in minutes between this and another moment
  * 
  * ### Arguments
  * * `other` - The moment to calculate difference from
  * 
  * ### Returns
  * Difference in minutes (positive if this moment is after the other)
  */
  diffMinutes(other: Moment): bigint;
  /**
  * Calculate the difference in hours between this and another moment
  * 
  * ### Arguments
  * * `other` - The moment to calculate difference from
  * 
  * ### Returns
  * Difference in hours (positive if this moment is after the other)
  */
  diffHours(other: Moment): bigint;
  /**
  * Calculate the difference in days between this and another moment
  * 
  * ### Arguments
  * * `other` - The moment to calculate difference from
  * 
  * ### Returns
  * Difference in days (positive if this moment is after the other)
  */
  diffDays(other: Moment): bigint;
  /**
  * Calculate the difference in months between this and another moment
  * 
  * ### Arguments
  * * `other` - The moment to calculate difference from
  * 
  * ### Returns
  * Difference in months (positive if this moment is after the other)
  */
  diffMonths(other: Moment): bigint;
  /**
  * Calculate the difference in years between this and another moment
  * 
  * ### Arguments
  * * `other` - The moment to calculate difference from
  * 
  * ### Returns
  * Difference in years (positive if this moment is after the other)
  */
  diffYears(other: Moment): bigint;
  /**
  * Check if the moment represents a valid date and time
  * 
  * ### Returns
  * True if the moment is valid, false if it represents an invalid date/time
  */
  isValid(): boolean;
  /**
  * Check if the moment's year is a leap year
  * 
  * ### Returns
  * True if the year is a leap year (has 366 days), false otherwise
  */
  isLeapYear(): boolean;
  /**
  * Create a copy of this moment
  * 
  * ### Returns
  * A new `Moment` instance that is an exact copy of this moment
  */
  clone(): Moment;
}
